import { createHash } from "node:crypto";
import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { z } from "zod";
import { PreferenceReceiptSchema, PreferencesSchema } from "./contracts";
import { initializeHome, loadHome, workspaceFor } from "./home";
import { expandPath } from "./paths";
import { observeWorkspace } from "./workspace";

function digest(path: string): string {
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}

function migrateRecord(value: unknown): unknown {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return value;
  const record = { ...(value as Record<string, unknown>) };
  if (record.namespace === "atthis") record.namespace = "rosso";
  if (typeof record.version === "string" && record.version.startsWith("atthis.")) {
    record.version = `rosso.${record.version.slice("atthis.".length)}`;
  }
  return record;
}

function filesBelow(root: string): string[] {
  const files: string[] = [];
  const pending = [root];
  while (pending.length > 0) {
    const current = pending.pop()!;
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const path = join(current, entry.name);
      if (entry.isSymbolicLink()) continue;
      if (entry.isDirectory()) pending.push(path);
      else if (entry.isFile()) files.push(path);
    }
  }
  return files.sort();
}

function migrateNamespaceFiles(home: string): void {
  for (const path of filesBelow(home)) {
    if (path.endsWith(".json")) {
      const current = JSON.parse(readFileSync(path, "utf8"));
      const migrated = migrateRecord(current);
      if (JSON.stringify(migrated) !== JSON.stringify(current)) {
        writeFileSync(path, `${JSON.stringify(migrated, null, 2)}\n`, "utf8");
      }
    } else if (path.endsWith(".jsonl")) {
      const original = readFileSync(path, "utf8");
      let changed = false;
      const lines = original.split(/\r?\n/).map((line, index) => {
        if (!line.trim()) return line;
        let current: unknown;
        try {
          current = JSON.parse(line);
        } catch (error: unknown) {
          throw new Error(`invalid JSONL in ${path} at line ${index + 1}: ${error instanceof Error ? error.message : String(error)}`);
        }
        const migrated = migrateRecord(current);
        if (JSON.stringify(migrated) !== JSON.stringify(current)) changed = true;
        return JSON.stringify(migrated);
      });
      if (changed) writeFileSync(path, lines.join("\n"), "utf8");
    }
  }
}

function readObject(path: string): Record<string, unknown> {
  const value = JSON.parse(readFileSync(path, "utf8"));
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`expected a JSON object in ${path}`);
  }
  return value as Record<string, unknown>;
}

function validateLegacySource(source: string): void {
  const manifest = readObject(join(source, "manifest.json"));
  if (manifest.version !== "atthis.home.v1") throw new Error("legacy manifest version must be atthis.home.v1");
  if (manifest.namespace !== "atthis") throw new Error("legacy manifest namespace must be atthis");
  const projects = readObject(join(source, "config", "projects.json"));
  if (projects.version !== "atthis.projects.v1") throw new Error("legacy projects version must be atthis.projects.v1");
}

function reconcileObsoleteMachinePreferences(home: string): void {
  const path = join(home, "state", "preferences.json");
  if (!existsSync(path)) return;
  const parsed = PreferencesSchema.parse(JSON.parse(readFileSync(path, "utf8")));
  if (parsed.preferences.length > 0) {
    throw new Error("legacy machine preferences require explicit environment reconciliation before migration");
  }
  rmSync(path);
}

function reconcileLegacyPreferenceReceipts(home: string): void {
  const path = join(home, "receipts", "preferences.jsonl");
  if (!existsSync(path)) return;
  const original = readFileSync(path, "utf8");
  let changed = false;
  const lines = original.split(/\r?\n/).map((line, index) => {
    if (!line.trim()) return line;
    let receipt: Record<string, unknown>;
    try {
      receipt = readRecord(line);
    } catch (error: unknown) {
      throw new Error(`invalid preference receipt at line ${index + 1}: ${error instanceof Error ? error.message : String(error)}`);
    }
    if (receipt.version === "rosso.preference-receipt.v2") {
      PreferenceReceiptSchema.parse(receipt);
      return JSON.stringify(receipt);
    }
    if (receipt.version !== "rosso.preference-receipt.v1") {
      throw new Error(`preference receipt at line ${index + 1} has an unsupported version`);
    }
    const expectedFields = ["action", "at", "id", "projectId", "recordDigest", "scope", "version"];
    if (Object.keys(receipt).sort().join("\0") !== expectedFields.join("\0")) {
      throw new Error(`preference receipt at line ${index + 1} has invalid fields`);
    }
    if (receipt.scope === "machine") {
      throw new Error("legacy machine preference receipts require explicit environment reconciliation before migration");
    }
    if (receipt.scope !== "user") {
      throw new Error(`preference receipt at line ${index + 1} has an invalid scope`);
    }
    const migrated = PreferenceReceiptSchema.parse({
      version: "rosso.preference-receipt.v2",
      at: receipt.at,
      action: receipt.action,
      id: receipt.id,
      projectId: receipt.projectId,
      recordDigest: receipt.recordDigest,
    });
    changed = true;
    return JSON.stringify(migrated);
  });
  if (changed) writeFileSync(path, lines.join("\n"), "utf8");
}

function readRecord(value: string): Record<string, unknown> {
  const parsed = JSON.parse(value);
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("expected a JSON object");
  }
  return parsed as Record<string, unknown>;
}

function sortedJson(value: Record<string, unknown>): string {
  return JSON.stringify(Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right))));
}

const migrationMarkerName = ".rossovia-namespace-migration.json";
const MigrationMarkerSchema = z.object({
  version: z.literal("rosso.namespace-migration.v1"),
  sourceHome: z.string().min(1),
  targetHome: z.string().min(1),
}).strict();

function clearMigrationTarget(target: string): void {
  for (const entry of readdirSync(target, { withFileTypes: true })) {
    if (entry.name === migrationMarkerName) continue;
    rmSync(join(target, entry.name), { recursive: true, force: true });
  }
}

function prepareMigrationTarget(source: string, target: string): string {
  const marker = join(target, migrationMarkerName);
  if (existsSync(target)) {
    if (!existsSync(marker)) throw new Error(`rossovia workbench target home already exists: ${target}`);
    const interrupted = MigrationMarkerSchema.parse(JSON.parse(readFileSync(marker, "utf8")));
    if (interrupted.sourceHome !== source || interrupted.targetHome !== target) {
      throw new Error(`rossovia workbench target contains an unrelated migration transaction: ${target}`);
    }
    clearMigrationTarget(target);
  } else {
    mkdirSync(target, { recursive: true });
  }
  writeFileSync(marker, `${JSON.stringify({
    version: "rosso.namespace-migration.v1",
    sourceHome: source,
    targetHome: target,
  }, null, 2)}\n`, "utf8");
  return marker;
}

function copyLegacyHome(source: string, target: string): void {
  if (existsSync(join(source, migrationMarkerName))) {
    throw new Error(`legacy source contains reserved migration marker: ${migrationMarkerName}`);
  }
  for (const entry of readdirSync(source, { withFileTypes: true })) {
    cpSync(join(source, entry.name), join(target, entry.name), { recursive: true, dereference: false });
  }
}

export function migrateLegacyHome(homeArgument?: string, fromHomeArgument?: string): {
  migrated: true;
  sourceHome: string;
  targetHome: string;
  verifiedProjectId: string | null;
  receipt: string;
} {
  const source = expandPath(fromHomeArgument ?? "~/.atthis");
  const target = expandPath(homeArgument ?? process.env.ROSSO_HOME ?? "~/.rosso");
  if (source === target) throw new Error("legacy source and rossovia workbench target home must differ");
  if (!existsSync(source) || !statSync(source).isDirectory()) {
    throw new Error(`legacy Atthis home does not exist: ${source}`);
  }
  const sourceManifest = join(source, "manifest.json");
  const sourceProjects = join(source, "config", "projects.json");
  for (const required of [sourceManifest, sourceProjects]) {
    if (!existsSync(required) || !statSync(required).isFile()) {
      throw new Error(`required legacy Atthis source not found: ${required}`);
    }
  }
  validateLegacySource(source);
  const sourceManifestDigest = digest(sourceManifest);
  const sourceProjectsDigest = digest(sourceProjects);
  let verifiedProjectId: string | null = null;
  const marker = prepareMigrationTarget(source, target);
  try {
    copyLegacyHome(source, target);
    migrateNamespaceFiles(target);
    reconcileLegacyPreferenceReceipts(target);
    reconcileObsoleteMachinePreferences(target);
    initializeHome(target);
    const current = loadHome(target);
    const verificationErrors: string[] = [];
    for (const project of current.projects.projects) {
      try {
        observeWorkspace(project, workspaceFor(current.workspaces, project.id));
        verifiedProjectId = project.id;
        break;
      } catch (error: unknown) {
        verificationErrors.push(`${project.id}: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    if (current.projects.projects.length > 0 && !verifiedProjectId) {
      throw new Error(`no migrated project could be verified: ${verificationErrors.join("; ")}`);
    }
    const receipt = {
      version: "rosso.namespace-migration-receipt.v1",
      at: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
      fromNamespace: "atthis",
      toNamespace: "rosso",
      sourceHome: source,
      targetHome: target,
      sourceManifestDigest,
      sourceProjectsDigest,
      verifiedProjectId,
    };
    writeFileSync(join(target, "receipts", "namespace-migrations.jsonl"), `${sortedJson(receipt)}\n`, "utf8");
    rmSync(marker);
  } catch (error: unknown) {
    try {
      clearMigrationTarget(target);
    } catch {
      // Preserve the migration failure. The marker keeps the target retryable.
    }
    throw error;
  }
  return {
    migrated: true,
    sourceHome: source,
    targetHome: target,
    verifiedProjectId,
    receipt: join(target, "receipts", "namespace-migrations.jsonl"),
  };
}

import { randomUUID } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type { z } from "zod";
import {
  ManifestSchema,
  PreferencesSchema,
  ProjectsSchema,
  RootsSchema,
  WorkspaceIndexSchema,
  WorkspacesSchema,
  type Projects,
  type Preferences,
  type Roots,
  type Workspace,
  type WorkspaceIndex,
  type Workspaces,
} from "./contracts";
import { expandPath } from "./paths";
import { repositoryLocator } from "./workspace";

export interface HomeSources {
  home: string;
  projects: Projects;
  roots: Roots;
  workspaces: Workspaces;
}

export interface InitializedHome {
  home: string;
  roots: Roots;
  index: WorkspaceIndex;
  writeAccess: "verified";
}

const homeDirectories = ["config", "state", "receipts", "cache"];

export function resolveHome(homeArgument?: string): string {
  return expandPath(homeArgument ?? process.env.ROSSO_HOME ?? "~/.rosso");
}

function fold(value: string): string {
  return value.toLowerCase();
}

export function loadJson<Schema extends z.ZodType>(path: string, schema: Schema): z.infer<Schema> {
  if (!existsSync(path)) throw new Error(`required rossovia workbench source not found: ${path}`);
  return schema.parse(JSON.parse(readFileSync(path, "utf8")));
}

export function saveJson(path: string, value: unknown): void {
  const serialized = `${JSON.stringify(value, null, 2)}\n`;
  const temporary = `${path}.${randomUUID()}.tmp`;
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(temporary, serialized, "utf8");
    renameSync(temporary, path);
  } catch (error: unknown) {
    removeProbe(temporary);
    throw new Error(
      `cannot persist Rossovia state at ${path}: ${error instanceof Error ? error.message : String(error)}. `
      + "The current runtime must grant write access to this exact state location.",
    );
  }
}

function verifyDirectoryWrite(directory: string): void {
  const temporary = join(directory, `.rossovia-write-probe-${randomUUID()}.tmp`);
  const renamed = `${temporary}.renamed`;
  try {
    writeFileSync(temporary, "", { encoding: "utf8", flag: "wx" });
    renameSync(temporary, renamed);
    rmSync(renamed);
  } catch (error: unknown) {
    removeProbe(temporary);
    removeProbe(renamed);
    throw new Error(
      `Rossovia home is readable but a required write surface is not writable by the current runtime: ${directory}: `
      + `${error instanceof Error ? error.message : String(error)}. `
      + "Grant write access to the exact ROSSO_HOME and start a fresh agent session before retrying.",
    );
  }
}

function verifyHomeWrite(home: string): void {
  for (const directory of [home, ...homeDirectories.map((entry) => join(home, entry))]) {
    verifyDirectoryWrite(directory);
  }
}

function prepareHomeDirectories(home: string): void {
  try {
    for (const directory of homeDirectories) mkdirSync(join(home, directory), { recursive: true });
  } catch (error: unknown) {
    throw new Error(
      `Rossovia home cannot be prepared by the current runtime: ${home}: `
      + `${error instanceof Error ? error.message : String(error)}. `
      + "Grant write access to the exact ROSSO_HOME and start a fresh agent session before retrying.",
    );
  }
}

function removeProbe(path: string): void {
  try {
    rmSync(path, { force: true });
  } catch {
    // Preserve the original write failure. A later init probe uses a unique name.
  }
}

export function validateProjects(projects: Projects): Projects {
  const ids = new Set<string>();
  const lookup = new Map<string, string>();
  for (const project of projects.projects) {
    const foldedId = fold(project.id);
    if (ids.has(foldedId)) throw new Error(`duplicate project id: ${project.id}`);
    ids.add(foldedId);
    const existingId = lookup.get(foldedId);
    if (existingId && existingId !== project.id) {
      throw new Error(`project lookup key '${project.id}' belongs to both ${existingId} and ${project.id}`);
    }
    lookup.set(foldedId, project.id);
    if (repositoryLocator(project.repository) !== project.repository) {
      throw new Error(`project ${project.id}.repository must be a credential-free canonical locator`);
    }
    const aliases = project.aliases.map(fold);
    if (new Set(aliases).size !== aliases.length) throw new Error(`project ${project.id} aliases must be unique`);
    for (const alias of aliases) {
      const owner = lookup.get(alias);
      if (owner && owner !== project.id) {
        throw new Error(`project lookup key '${alias}' belongs to both ${owner} and ${project.id}`);
      }
      lookup.set(alias, project.id);
    }
  }
  return projects;
}

export function validateWorkspaces(workspaces: Workspaces): Workspaces {
  const ids = new Set<string>();
  for (const workspace of workspaces.workspaces) {
    if (ids.has(workspace.projectId)) throw new Error(`duplicate workspace mapping: ${workspace.projectId}`);
    ids.add(workspace.projectId);
  }
  return workspaces;
}

export function validateRoots(roots: Roots): Roots {
  if (new Set(roots.roots).size !== roots.roots.length) {
    throw new Error("workspace roots must be unique");
  }
  return roots;
}

export function validateIndex(index: WorkspaceIndex): WorkspaceIndex {
  const paths = new Set<string>();
  for (const entry of index.entries) {
    if (paths.has(entry.path)) throw new Error(`duplicate indexed workspace path: ${entry.path}`);
    paths.add(entry.path);
    if (entry.repository !== null && repositoryLocator(entry.repository) !== entry.repository) {
      throw new Error(`indexed workspace ${entry.path}.repository must be a credential-free canonical locator`);
    }
  }
  return index;
}

export function validatePreferences(preferences: Preferences, label: string): Preferences {
  const identities = new Set<string>();
  for (const preference of preferences.preferences) {
    const identity = `${fold(preference.id)}\0${preference.projectId ? fold(preference.projectId) : ""}`;
    if (identities.has(identity)) {
      throw new Error(`duplicate ${label} preference: ${preference.id} for ${preference.projectId ?? "all projects"}`);
    }
    identities.add(identity);
  }
  return preferences;
}

function now(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
}

function ensureJson<Schema extends z.ZodType>(
  path: string,
  schema: Schema,
  initial: z.input<Schema>,
  validate: (value: z.infer<Schema>) => z.infer<Schema> = (value) => value,
): z.infer<Schema> {
  if (!existsSync(path)) saveJson(path, initial);
  return validate(loadJson(path, schema));
}

export function initializeHome(homeArgument?: string): InitializedHome {
  const home = resolveHome(homeArgument);
  prepareHomeDirectories(home);
  verifyHomeWrite(home);
  ensureJson(join(home, "manifest.json"), ManifestSchema, {
    version: "rosso.home.v1",
    namespace: "rosso",
    createdAt: now(),
  });
  ensureJson(join(home, "config", "projects.json"), ProjectsSchema, {
    version: "rosso.projects.v1",
    projects: [],
  }, validateProjects);
  ensureJson(join(home, "state", "workspaces.json"), WorkspacesSchema, {
    version: "rosso.workspaces.v1",
    workspaces: [],
  }, validateWorkspaces);
  const roots = ensureJson(join(home, "state", "roots.json"), RootsSchema, {
    version: "rosso.roots.v1",
    roots: [],
  }, validateRoots);
  ensureJson(join(home, "config", "preferences.json"), PreferencesSchema, {
    version: "rosso.preferences.v1",
    preferences: [],
  }, (value) => validatePreferences(value, "user preferences"));
  const index = ensureJson(join(home, "cache", "workspaces.json"), WorkspaceIndexSchema, {
    version: "rosso.workspace-index.v1",
    generatedAt: now(),
    entries: [],
  }, validateIndex);
  return { home, roots, index, writeAccess: "verified" };
}

export function loadHome(homeArgument?: string): HomeSources {
  const home = resolveHome(homeArgument);
  loadJson(join(home, "manifest.json"), ManifestSchema);
  const projects = validateProjects(loadJson(join(home, "config", "projects.json"), ProjectsSchema));
  const workspaces = validateWorkspaces(loadJson(join(home, "state", "workspaces.json"), WorkspacesSchema));
  const roots = validateRoots(loadJson(join(home, "state", "roots.json"), RootsSchema));
  return { home, projects, roots, workspaces };
}

export function loadWorkspaceIndex(home: string): WorkspaceIndex {
  return validateIndex(loadJson(join(home, "cache", "workspaces.json"), WorkspaceIndexSchema));
}

export function workspaceFor(workspaces: Workspaces, projectId: string): Workspace {
  const matches = workspaces.workspaces.filter((workspace) => workspace.projectId === projectId);
  if (matches.length === 0) throw new Error(`no local workspace is attached for ${projectId}`);
  return matches[0]!;
}

import { afterEach, describe, expect, test } from "bun:test";
import { existsSync, mkdtempSync, mkdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const repositoryRoot = resolve(import.meta.dir, "../../..");
const bunCli = join(repositoryRoot, "operations", "workbench", "src", "cli.ts");
const temporaryRoots: string[] = [];

afterEach(() => {
  for (const root of temporaryRoots.splice(0)) rmSync(root, { recursive: true, force: true });
});

function command(argv: string[], cwd = repositoryRoot): { exitCode: number; stdout: string; stderr: string } {
  const result = Bun.spawnSync(argv, { cwd, stdout: "pipe", stderr: "pipe" });
  return {
    exitCode: result.exitCode,
    stdout: result.stdout.toString(),
    stderr: result.stderr.toString(),
  };
}

function workbench(home: string, ...args: string[]) {
  return command([process.execPath, bunCli, "--home", home, ...args]);
}

function git(cwd: string, ...args: string[]): void {
  const result = command(["git", ...args], cwd);
  if (result.exitCode !== 0) throw new Error(result.stderr);
}

function writeJson(path: string, value: unknown): void {
  mkdirSync(resolve(path, ".."), { recursive: true });
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

function createRepository(path: string): void {
  mkdirSync(path, { recursive: true });
  git(path, "init");
  git(path, "config", "user.name", "Rossovia Test");
  git(path, "config", "user.email", "rossovia@example.test");
  writeFileSync(join(path, "README.md"), "# Fixture\n");
  git(path, "add", "README.md");
  git(path, "commit", "-m", "initial");
  git(path, "remote", "add", "origin", "https://example.test/lidessen/migration.git");
}

function createLegacyHome(home: string, repository: string, machinePreferences: unknown[] = []): void {
  writeJson(join(home, "manifest.json"), {
    version: "atthis.home.v1",
    namespace: "atthis",
    createdAt: "2026-07-18T00:00:00Z",
  });
  writeJson(join(home, "config", "projects.json"), {
    version: "atthis.projects.v1",
    projects: [{
      id: "repository:migration",
      repository: "https://example.test/lidessen/migration.git",
      aliases: ["migration"],
    }],
  });
  writeJson(join(home, "config", "preferences.json"), {
    version: "atthis.preferences.v1",
    preferences: [{
      id: "execution-carrier",
      statement: "Prefer Work Cell for bounded work.",
      source: "user-explicit",
      recordedAt: "2026-07-18T00:00:00Z",
      updatedAt: "2026-07-18T00:00:00Z",
    }],
  });
  writeJson(join(home, "state", "workspaces.json"), {
    version: "atthis.workspaces.v1",
    workspaces: [{ projectId: "repository:migration", path: repository }],
  });
  writeJson(join(home, "state", "roots.json"), { version: "atthis.roots.v1", roots: [] });
  writeJson(join(home, "state", "preferences.json"), {
    version: "atthis.preferences.v1",
    preferences: machinePreferences,
  });
  writeJson(join(home, "cache", "workspaces.json"), {
    version: "atthis.workspace-index.v1",
    generatedAt: "2026-07-18T00:00:00Z",
    entries: [],
  });
  writeJson(join(home, "cognition", "artifact.json"), {
    version: "atthis.cognitive-artifact.v1",
    metadata: { version: "atthis.user-content.v1" },
  });
  mkdirSync(join(home, "receipts"), { recursive: true });
  writeFileSync(join(home, "receipts", "preferences.jsonl"), `${JSON.stringify({
    version: "atthis.preference-receipt.v1",
    at: "2026-07-18T00:00:00Z",
    action: "set",
    scope: "user",
    id: "execution-carrier",
    projectId: null,
    recordDigest: "0".repeat(64),
  })}\n`, "utf8");
}

describe("legacy namespace migration", () => {
  test("moves the retained source into the corrected Bun workbench contract", () => {
    const root = mkdtempSync(join(tmpdir(), "rossovia-migration-"));
    temporaryRoots.push(root);
    const repository = join(root, "repository");
    const source = join(root, "legacy-atthis");
    const target = join(root, "rossovia");
    createRepository(repository);
    createLegacyHome(source, repository);
    const sourceManifest = readFileSync(join(source, "manifest.json"), "utf8");

    const migrated = workbench(target, "migrate", "--from-home", source);
    expect(migrated.exitCode).toBe(0);
    expect(JSON.parse(migrated.stdout)).toEqual(expect.objectContaining({
      migrated: true,
      sourceHome: realpathSync(source),
      targetHome: join(realpathSync(root), "rossovia"),
      verifiedProjectId: "repository:migration",
    }));
    expect(readFileSync(join(source, "manifest.json"), "utf8")).toBe(sourceManifest);
    expect(JSON.parse(readFileSync(join(target, "manifest.json"), "utf8"))).toEqual(expect.objectContaining({
      version: "rosso.home.v1",
      namespace: "rosso",
    }));
    expect(existsSync(join(target, "state", "preferences.json"))).toBe(false);
    const artifact = JSON.parse(readFileSync(join(target, "cognition", "artifact.json"), "utf8"));
    expect(artifact.version).toBe("rosso.cognitive-artifact.v1");
    expect(artifact.metadata.version).toBe("atthis.user-content.v1");
    expect(workbench(target, "resolve", "migration").exitCode).toBe(0);
    expect(existsSync(join(target, "receipts", "namespace-migrations.jsonl"))).toBe(true);
    expect(existsSync(join(target, ".rossovia-namespace-migration.json"))).toBe(false);
    expect(existsSync(`${target}.namespace-migration.tmp`)).toBe(false);
    const applicable = JSON.parse(workbench(target, "preference", "list").stdout);
    expect(applicable.preferences[0].statement).toBe("Prefer Work Cell for bounded work.");
    const preferenceReceipt = JSON.parse(readFileSync(join(target, "receipts", "preferences.jsonl"), "utf8").trim());
    expect(preferenceReceipt.version).toBe("rosso.preference-receipt.v2");
    expect(preferenceReceipt).not.toHaveProperty("scope");

    const rerun = workbench(target, "migrate", "--from-home", source);
    expect(rerun.exitCode).toBe(2);
    expect(rerun.stderr).toContain("target home already exists");
  });

  test("restarts an interrupted migration inside the exact target home", () => {
    const root = mkdtempSync(join(tmpdir(), "rossovia-interrupted-migration-"));
    temporaryRoots.push(root);
    const repository = join(root, "repository");
    const source = join(root, "legacy-atthis");
    const target = join(root, "rossovia");
    createRepository(repository);
    createLegacyHome(source, repository);
    mkdirSync(target);
    writeJson(join(target, ".rossovia-namespace-migration.json"), {
      version: "rosso.namespace-migration.v1",
      sourceHome: realpathSync(source),
      targetHome: realpathSync(target),
    });
    writeFileSync(join(target, "partial"), "incomplete");

    const migrated = workbench(target, "migrate", "--from-home", source);
    expect(migrated.exitCode).toBe(0);
    expect(existsSync(join(target, "partial"))).toBe(false);
    expect(existsSync(join(target, ".rossovia-namespace-migration.json"))).toBe(false);
    expect(existsSync(`${target}.namespace-migration.tmp`)).toBe(false);
    expect(workbench(target, "resolve", "migration").exitCode).toBe(0);
  });

  test("refuses to reinterpret nonempty machine preferences", () => {
    const root = mkdtempSync(join(tmpdir(), "rossovia-machine-preference-rejection-"));
    temporaryRoots.push(root);
    const repository = join(root, "repository");
    const source = join(root, "legacy-atthis");
    const target = join(root, "rossovia");
    createRepository(repository);
    createLegacyHome(source, repository, [{
      id: "provider-order",
      statement: "Prefer a local provider.",
      source: "user-explicit",
      recordedAt: "2026-07-18T00:00:00Z",
      updatedAt: "2026-07-18T00:00:00Z",
    }]);
    const rejected = workbench(target, "migrate", "--from-home", source);
    expect(rejected.exitCode).toBe(2);
    expect(rejected.stderr).toContain("require explicit environment reconciliation");
    expect(existsSync(join(target, ".rossovia-namespace-migration.json"))).toBe(true);
    expect(existsSync(join(target, "manifest.json"))).toBe(false);
  });

  test("refuses to reinterpret machine-scoped receipt history", () => {
    const root = mkdtempSync(join(tmpdir(), "rossovia-machine-receipt-rejection-"));
    temporaryRoots.push(root);
    const repository = join(root, "repository");
    const source = join(root, "legacy-atthis");
    const target = join(root, "rossovia");
    createRepository(repository);
    createLegacyHome(source, repository);
    const receiptPath = join(source, "receipts", "preferences.jsonl");
    const receipt = JSON.parse(readFileSync(receiptPath, "utf8"));
    receipt.scope = "machine";
    writeFileSync(receiptPath, `${JSON.stringify(receipt)}\n`, "utf8");
    const rejected = workbench(target, "migrate", "--from-home", source);
    expect(rejected.exitCode).toBe(2);
    expect(rejected.stderr).toContain("machine preference receipts require explicit environment reconciliation");
    expect(existsSync(join(target, ".rossovia-namespace-migration.json"))).toBe(true);
    expect(existsSync(join(target, "manifest.json"))).toBe(false);
  });
});

